style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Apply background to html, body, and main containers */
    html, body, #container, .container-main, .container-fluid {
        background: url("https://imgur.com/a/MDzEMU9") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: transparent !important;
    }

    /* Remove background from common content wrappers so image shows through */
    .site-content, .content, .main-section {
        background: transparent !important;
    }

    /* Optional: make header semi-transparent so background is visible */
    header, .rbx-navbar {
        background: rgba(0,0,0,0.5) !important;
    }

    /* Optional: make text readable */
    body, .text-label, .font, .font-caption {
        color: white !important;
    }
}
